import{_ as t,o,c as r,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const c=JSON.parse('{"title":"第 8 章 AI 团队：一句话召唤多智能体协作（易懂版）","description":"","frontmatter":{},"headers":[],"relativePath":"easy/第8章 AI 团队：一句话召唤多智能体协作（易懂版）.md","filePath":"easy/第8章 AI 团队：一句话召唤多智能体协作（易懂版）.md"}'),l={name:"easy/第8章 AI 团队：一句话召唤多智能体协作（易懂版）.md"};function s(n,a,i,h,_,d){return o(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="第-8-章-ai-团队-一句话召唤多智能体协作-易懂版" tabindex="-1">第 8 章 AI 团队：一句话召唤多智能体协作（易懂版） <a class="header-anchor" href="#第-8-章-ai-团队-一句话召唤多智能体协作-易懂版" aria-label="Permalink to &quot;第 8 章 AI 团队：一句话召唤多智能体协作（易懂版）&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📖 想读完整版？</p><p>这页是<strong>易懂版</strong>，用大白话讲重点。想系统学习，请读 [第 8 章 AI 团队：一句话召唤多智能体协作（完整版）](../../bluebook/第一篇 使用手册：先把我用起来/第 8 章 AI 团队：一句话召唤多智能体协作.md)。</p></div><h2 id="这章讲什么-一句话" tabindex="-1">这章讲什么（一句话） <a class="header-anchor" href="#这章讲什么-一句话" aria-label="Permalink to &quot;这章讲什么（一句话）&quot;">​</a></h2><p><strong>任务太重一个人干不完？叫几个&quot;分身&quot;组队，我当队长分活给他们。</strong></p><h2 id="先打个比方" tabindex="-1">先打个比方 <a class="header-anchor" href="#先打个比方" aria-label="Permalink to &quot;先打个比方&quot;">​</a></h2><p>一家店生意好到一个人忙不过来，老板招几个员工，<strong>自己当店长</strong>：有人做菜、有人收银、有人送外卖，各管一摊，店长统筹。</p><p>AI 团队就是这个：<strong>一个我当组长，拉几个 AI 成员分工干活。</strong></p><h2 id="核心就-3-件事" tabindex="-1">核心就 3 件事 <a class="header-anchor" href="#核心就-3-件事" aria-label="Permalink to &quot;核心就 3 件事&quot;">​</a></h2><ol><li><strong>组长负责制</strong>：我当 Leader，负责理解你的目标、给成员派活、汇总检查结果。</li><li><strong>成员分工</strong>：按角色拆分——写代码的、写文档的、测 bug 的……各干各的活。</li><li><strong>你只管发话</strong>：你只需要说&quot;我要什么&quot;，组队、分工、协调我来搞定。</li></ol><h2 id="什么时候该组队" tabindex="-1">什么时候该组队？ <a class="header-anchor" href="#什么时候该组队" aria-label="Permalink to &quot;什么时候该组队？&quot;">​</a></h2><ul><li>✅ 任务<strong>横跨多种能力</strong>（要写文档又要写代码又要测）；</li><li>✅ 工作量<strong>大</strong>（一个人要干很久）；</li><li>✅ 需要<strong>并行</strong>（两个环节互不依赖，同时干更快）；</li><li>⚠️ 小任务别组队——<strong>一个人的事，组队反而更慢</strong>。</li></ul><h2 id="上手小例子" tabindex="-1">上手小例子 <a class="header-anchor" href="#上手小例子" aria-label="Permalink to &quot;上手小例子&quot;">​</a></h2><blockquote><p><strong>指令</strong>：&quot;组个团队：开发一个网页版周报工具，一人写页面、一人写逻辑、一人测试。&quot;</p><p><strong>你会看到</strong>：我建团队 → 给每个成员派任务 → 他们并行干活 → 我汇总结果给你。</p></blockquote><h2 id="别踩的坑" tabindex="-1">别踩的坑 <a class="header-anchor" href="#别踩的坑" aria-label="Permalink to &quot;别踩的坑&quot;">​</a></h2><ul><li>❌ 大事小事都组队——<strong>小任务单人干，大任务才组队</strong>；</li><li>❌ 组了队就不管——<strong>你照样要检查总成果</strong>；</li><li>❌ 分工不清——目标说不清楚，团队越大越乱。</li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p><strong>大任务 = 组队 → 我当组长分活 → 成员并行干 → 我汇总验收。</strong></p><h2 id="一分钟测试" tabindex="-1">一分钟测试 <a class="header-anchor" href="#一分钟测试" aria-label="Permalink to &quot;一分钟测试&quot;">​</a></h2><p>下次接到大任务，问：<strong>&quot;这个活需要几个人分工吗？&quot;</strong> 需要就说&quot;组个团队&quot;，不需要就单干。</p><p>👉 [下一章：写文档，报告、方案与白皮书（易懂版）](第9章 写文档：报告、方案与白皮书（易懂版）.md)</p>',20)])])}const g=t(l,[["render",s]]);export{c as __pageData,g as default};
